window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a85aad35a7f2f2ad"]={"versions": [{"id": "FIG-a85aad35a7f2f2ad", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Phasendiagramm) zur Darstellung der clientseitigen Kommunikationsphasen und des Nachrichtenversands im AUTOSAR Service Discovery (SD) Modul. Das Diagramm ordnet die clientseitigen Zustände und Ereignisse auf einer kontinuierlichen horizontalen Zeitachse an.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>DOWN</strong>: Ausgangszustand vor Aktivierung des Service-Clients bzw. vor Eintreffen eines Client-Requests.</li>\n<li><strong>Client Request</strong>: Externes Trigger-Ereignis (symbolisiert durch Blitz-Symbole), das die Service-Suche initiiert bzw. innerhalb der Repetition Phase erneut auftritt.</li>\n<li><strong>Phasenabschnitte</strong>:</li>\n<li><code>Initial Wait Phase</code>: Wartezeitraum zwischen Request und erstem Nachrichtenversand.</li>\n<li><code>Repetition Phase</code>: Wiederholungsphase mit exponentiell oder gestaffelt wachsenden Sendeintervallen.</li>\n<li><code>Main Phase</code>: Zyklische Betriebsphase zur kontinuierlichen Suche/Aufrechterhaltung nach Abschluss der Repetition Phase.</li>\n<li><strong>Nachrichtenereignisse</strong>:</li>\n<li>Vertikale grüne Pfeile nach unten: Regulär gesendete FindService-Nachrichten.</li>\n<li>Vertikaler blauer Pfeil nach unten: Asynchron oder vorzeitig ausgelöste Sendung bei erneutem Client Request.</li>\n<li>Rote Kreuze: Unterdrückte/gestrichene Sendezeitpunkte infolge von Zustandsänderungen oder vorzeitigem Abbruch.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das System befindet sich initial im Zustand <code>DOWN</code>.</li>\n<li>Das Eintreffen eines <code>Client Request</code> beendet den <code>DOWN</code>-Zustand und startet die <code>Initial Wait Phase</code>.</li>\n<li>Nach Ablauf der <code>Initial Wait Phase</code> wechselt das SD-Modul in die <code>Repetition Phase</code> und sendet die erste Find-Nachricht (grüner Pfeil).</li>\n<li>Weitere Find-Nachrichten werden in definierten Intervallen gesendet. Ein während der <code>Repetition Phase</code> auftretender weiterer <code>Client Request</code> triggert eine vorgezogene Nachrichtenaussendung (blauer Pfeil).</li>\n<li>Nachfolgende reguläre Sendezeitpunkte der <code>Repetition Phase</code> werden bei erfolgreichem Matching oder Phasenende abgewiesen/unterdrückt (gekennzeichnet durch rote Kreuze).</li>\n<li>Nach Ablauf der <code>Repetition Phase</code> wird die <code>Main Phase</code> erreicht, in der regulär keine weiteren Wiederholungsnachrichten der vorherigen Phase mehr gesendet werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normativ verbindliches Timing-Verhalten für AUTOSAR Service Discovery Clients beim Auffinden von Diensten (FindService).</li>\n<li>Implementierer müssen das konfigurierbare Initial-Wait-Verhalten (<code>SdClientServiceInitialWaitDelayConfig</code>) sowie die exponentielle Backoff- bzw. Wiederholungslogik (<code>SdClientServiceRepetitionConfig</code>) exakt an die Trigger-Ereignisse koppeln.</li>\n<li>Zusätzliche Client-Requests während einer laufenden Repetition Phase erfordern das Zurücksetzen oder Anpassen der nächsten Sendezeitpunkte gemäß SD-Spezifikation.</li>\n</ul>"}, {"id": "FIG-21a32a23ed0985dc", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Phasendiagramm) zur Darstellung der clientseitigen Kommunikationsphasen und des Nachrichtenversands im AUTOSAR Service Discovery (SD) Modul. Das Diagramm ordnet die clientseitigen Zustände und Ereignisse auf einer kontinuierlichen horizontalen Zeitachse an.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>DOWN</strong>: Ausgangszustand vor Aktivierung des Service-Clients bzw. vor Eintreffen eines Client-Requests.</li>\n<li><strong>Client Request</strong>: Externes Trigger-Ereignis (symbolisiert durch Blitz-Symbole), das die Service-Suche initiiert bzw. innerhalb der Repetition Phase erneut auftritt.</li>\n<li><strong>Phasenabschnitte</strong>:</li>\n<li><code>Initial Wait Phase</code>: Wartezeitraum zwischen Request und erstem Nachrichtenversand.</li>\n<li><code>Repetition Phase</code>: Wiederholungsphase mit exponentiell oder gestaffelt wachsenden Sendeintervallen.</li>\n<li><code>Main Phase</code>: Zyklische Betriebsphase zur kontinuierlichen Suche/Aufrechterhaltung nach Abschluss der Repetition Phase.</li>\n<li><strong>Nachrichtenereignisse</strong>:</li>\n<li>Vertikale grüne Pfeile nach unten: Regulär gesendete FindService-Nachrichten.</li>\n<li>Vertikaler blauer Pfeil nach unten: Asynchron oder vorzeitig ausgelöste Sendung bei erneutem Client Request.</li>\n<li>Rote Kreuze: Unterdrückte/gestrichene Sendezeitpunkte infolge von Zustandsänderungen oder vorzeitigem Abbruch.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das System befindet sich initial im Zustand <code>DOWN</code>.</li>\n<li>Das Eintreffen eines <code>Client Request</code> beendet den <code>DOWN</code>-Zustand und startet die <code>Initial Wait Phase</code>.</li>\n<li>Nach Ablauf der <code>Initial Wait Phase</code> wechselt das SD-Modul in die <code>Repetition Phase</code> und sendet die erste Find-Nachricht (grüner Pfeil).</li>\n<li>Weitere Find-Nachrichten werden in definierten Intervallen gesendet. Ein während der <code>Repetition Phase</code> auftretender weiterer <code>Client Request</code> triggert eine vorgezogene Nachrichtenaussendung (blauer Pfeil).</li>\n<li>Nachfolgende reguläre Sendezeitpunkte der <code>Repetition Phase</code> werden bei erfolgreichem Matching oder Phasenende abgewiesen/unterdrückt (gekennzeichnet durch rote Kreuze).</li>\n<li>Nach Ablauf der <code>Repetition Phase</code> wird die <code>Main Phase</code> erreicht, in der regulär keine weiteren Wiederholungsnachrichten der vorherigen Phase mehr gesendet werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normativ verbindliches Timing-Verhalten für AUTOSAR Service Discovery Clients beim Auffinden von Diensten (FindService).</li>\n<li>Implementierer müssen das konfigurierbare Initial-Wait-Verhalten (<code>SdClientServiceInitialWaitDelayConfig</code>) sowie die exponentielle Backoff- bzw. Wiederholungslogik (<code>SdClientServiceRepetitionConfig</code>) exakt an die Trigger-Ereignisse koppeln.</li>\n<li>Zusätzliche Client-Requests während einer laufenden Repetition Phase erfordern das Zurücksetzen oder Anpassen der nächsten Sendezeitpunkte gemäß SD-Spezifikation.</li>\n</ul>"}, {"id": "FIG-65ed3d5f185dfa28", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Phasendiagramm) zur Darstellung der clientseitigen Kommunikationsphasen und des Nachrichtenversands im AUTOSAR Service Discovery (SD) Modul. Das Diagramm ordnet die clientseitigen Zustände und Ereignisse auf einer kontinuierlichen horizontalen Zeitachse an.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>DOWN</strong>: Ausgangszustand vor Aktivierung des Service-Clients bzw. vor Eintreffen eines Client-Requests.</li>\n<li><strong>Client Request</strong>: Externes Trigger-Ereignis (symbolisiert durch Blitz-Symbole), das die Service-Suche initiiert bzw. innerhalb der Repetition Phase erneut auftritt.</li>\n<li><strong>Phasenabschnitte</strong>:</li>\n<li><code>Initial Wait Phase</code>: Wartezeitraum zwischen Request und erstem Nachrichtenversand.</li>\n<li><code>Repetition Phase</code>: Wiederholungsphase mit exponentiell oder gestaffelt wachsenden Sendeintervallen.</li>\n<li><code>Main Phase</code>: Zyklische Betriebsphase zur kontinuierlichen Suche/Aufrechterhaltung nach Abschluss der Repetition Phase.</li>\n<li><strong>Nachrichtenereignisse</strong>:</li>\n<li>Vertikale grüne Pfeile nach unten: Regulär gesendete FindService-Nachrichten.</li>\n<li>Vertikaler blauer Pfeil nach unten: Asynchron oder vorzeitig ausgelöste Sendung bei erneutem Client Request.</li>\n<li>Rote Kreuze: Unterdrückte/gestrichene Sendezeitpunkte infolge von Zustandsänderungen oder vorzeitigem Abbruch.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das System befindet sich initial im Zustand <code>DOWN</code>.</li>\n<li>Das Eintreffen eines <code>Client Request</code> beendet den <code>DOWN</code>-Zustand und startet die <code>Initial Wait Phase</code>.</li>\n<li>Nach Ablauf der <code>Initial Wait Phase</code> wechselt das SD-Modul in die <code>Repetition Phase</code> und sendet die erste Find-Nachricht (grüner Pfeil).</li>\n<li>Weitere Find-Nachrichten werden in definierten Intervallen gesendet. Ein während der <code>Repetition Phase</code> auftretender weiterer <code>Client Request</code> triggert eine vorgezogene Nachrichtenaussendung (blauer Pfeil).</li>\n<li>Nachfolgende reguläre Sendezeitpunkte der <code>Repetition Phase</code> werden bei erfolgreichem Matching oder Phasenende abgewiesen/unterdrückt (gekennzeichnet durch rote Kreuze).</li>\n<li>Nach Ablauf der <code>Repetition Phase</code> wird die <code>Main Phase</code> erreicht, in der regulär keine weiteren Wiederholungsnachrichten der vorherigen Phase mehr gesendet werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normativ verbindliches Timing-Verhalten für AUTOSAR Service Discovery Clients beim Auffinden von Diensten (FindService).</li>\n<li>Implementierer müssen das konfigurierbare Initial-Wait-Verhalten (<code>SdClientServiceInitialWaitDelayConfig</code>) sowie die exponentielle Backoff- bzw. Wiederholungslogik (<code>SdClientServiceRepetitionConfig</code>) exakt an die Trigger-Ereignisse koppeln.</li>\n<li>Zusätzliche Client-Requests während einer laufenden Repetition Phase erfordern das Zurücksetzen oder Anpassen der nächsten Sendezeitpunkte gemäß SD-Spezifikation.</li>\n</ul>"}], "trans": [{"from": "FIG-a85aad35a7f2f2ad", "to": "FIG-21a32a23ed0985dc", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-21a32a23ed0985dc", "to": "FIG-65ed3d5f185dfa28", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
